120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
124	        Collection<Owner> owners;
125	        if (lastName != null) {
126	            owners = this.clinicService.findOwnerByLastName(lastName);
127	        } else {
128	            owners = this.clinicService.findAllOwners();
129	        }
130	        if (owners.isEmpty()) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        if (ownerFieldsDto != null) {
150	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
151	        }
152	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
153	        if (!missingFields.isEmpty()) {
154	            throw new MissingOwnerFieldsException(missingFields);
155	        }
156	        HttpHeaders headers = new HttpHeaders();
157	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
158	        Collection<Owner> sameLastName =
159	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
160	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
161	        applyHouseholdPolicy(owner, ownerFieldsDto, sameLastName);
162	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
163	        if (!this.clinicService.findOwnersByTelephone(normalizedTelephone).isEmpty()) {
164	            throw new DuplicateTelephoneException(normalizedTelephone);
165	        }
166	        owner.setTelephone(normalizedTelephone);
167	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
168	        if (owner.getRegistrationDate() == null) {
169	            owner.setRegistrationDate(LocalDate.now());
170	        }
171	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
172	        LocalDate registrationDate = owner.getRegistrationDate();
173	        if (clinicService.countOwnersByRegistrationDate(registrationDate)
174	                >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
175	            throw new DailyOwnerLimitException(registrationDate);
176	        }
177	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
178	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
179	            throw new CityOwnerLimitException(owner.getCity());
180	        }
181	        owner.setCustomerCode(customerCodeGenerator.generate(
182	            owner.getCity(), owner.getLastName(), cityOwnerCount));
183	        this.clinicService.saveOwner(owner);
184	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
185	        headers.setLocation(UriComponentsBuilder.newInstance()
186	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
187	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
188	    }
