234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Transactional
236	    @Override
237	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
238	        Owner owner = this.clinicService.findOwnerById(ownerId);
239	        if (owner == null) {
240	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	        }
242	        this.clinicService.deleteOwner(owner);
243	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
244	    }
245	
246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Override
248	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
249	        Owner owner = this.clinicService.findOwnerById(ownerId);
250	        if (owner == null) {
251	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
252	        }
253	        HttpHeaders headers = new HttpHeaders();
254	        Pet pet = petMapper.toPet(petFieldsDto);
255	        owner.setId(ownerId);
256	        pet.setOwner(owner);
257	        pet.getType().setName(null);
258	        this.clinicService.savePet(pet);
259	        PetDto petDto = petMapper.toPetDto(pet);
260	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
261	            .buildAndExpand(pet.getId()).toUri());
262	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
263	    }
264	
265	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
266	    @Override
267	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
268	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
269	        if (currentOwner != null) {
270	            Pet currentPet = this.clinicService.findPetById(petId);
271	            if (currentPet != null) {
272	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
273	                currentPet.setName(petFieldsDto.getName());
274	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
275	                this.clinicService.savePet(currentPet);
276	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
277	            }
278	        }
279	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
280	    }
281	
282	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
283	    @Override
284	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
285	        HttpHeaders headers = new HttpHeaders();
286	        Visit visit = visitMapper.toVisit(visitFieldsDto);
287	        Pet pet = new Pet();
288	        pet.setId(petId);
289	        visit.setPet(pet);
290	        this.clinicService.saveVisit(visit);
291	        VisitDto visitDto = visitMapper.toVisitDto(visit);
292	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
293	            .buildAndExpand(visit.getId()).toUri());
294	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
295	    }
296	
297	
298	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
299	    @Override
300	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
301	        Owner owner = this.clinicService.findOwnerById(ownerId);
302	        if (owner != null) {
303	            Pet pet = owner.getPet(petId);
304	            if (pet != null) {
305	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
306	            }
307	        }
308	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
309	    }
310	}
